#include <iostream>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;
#include <vector>
using std::vector;
#include <string>
using std::string;
using std::to_string;

typedef long long int ll;

const ll BITLEN = 6;
const ll BASE = 10;
vector<ll> make_pow (ll base, ll maxv) {
	vector<ll> ans(maxv+1, 0);
	ans[0] = 1;
	for (ll i = 1; i <= maxv; i++) {
		ans[i] = ans[i-1] * base;
	}
	return ans;
}
const vector<ll> pow10 = make_pow(BASE, BITLEN);

ll idtoidx (const string s) {
	ll x = 0;
	for (ll i = 0; i < BITLEN; i++) {
		x += (ll)(s[i] - '0') * pow10[i];
	}
	return x;
}
inline ll idxdigit (const ll x, const ll d) {
	return (x / pow10[d]) % BASE;
}

void output (const ll x) {
	cout << x << "\n";
}

ll n;
vector<string> s;
vector<ll> v;
ll q;

void solve () {
	vector<ll> zeta(pow10[BITLEN], 0);
	for (ll i = 0; i < n; i++) {
		zeta[idtoidx(s[i])] += v[i];
	}
	for (ll bi = 0; bi < BITLEN; bi++) {
		for (ll i = 0; i < pow10[BITLEN]; i++) {
			if (idxdigit(i, bi) > 0) {
				zeta[i] += zeta[i - pow10[bi]];
			}
		}
	}

	cin >> q;
	for (ll qi = 0; qi < q; qi++) {
		string sx, sy;
		cin >> sx >> sy;
		ll vx = idtoidx(sx);
		ll vy = idtoidx(sy);

		ll ans = 0;
		vector<ll> wx(BITLEN), wy(BITLEN);
		bool isnonzero = true;
		for (ll i = 0; i < BITLEN; i++) {
			wx[i] = idxdigit(vx, i);
			wy[i] = idxdigit(vy, i);

			if (wx[i] > wy[i]) isnonzero = false;
		}
		if (!isnonzero) {
			ans = 0;
			output(ans);
			continue;
		}

		for (ll bi = 0; !(bi >> BITLEN); bi++) {
			ll zidx = 0;
			ll bcnt = 0;
			bool isok = true;
			for (ll i = 0; i < BITLEN; i++) {
				if (bi & (1LL << i)) {
					// -
					bcnt += 1;
					if (wx[i] <= 0) isok = false;
					zidx += (wx[i] - 1) * pow10[i];
				} else {
					// +
					bcnt += 0;
					zidx += wy[i] * pow10[i];
				}
			}
			if (!isok) continue;

			if (bcnt % 2 == 0) {
				ans += zeta[zidx];
			} else {
				ans -= zeta[zidx];
			}
		}

		output(ans);
	}

	return;
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> n;
	s.resize(n);
	v.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> s[i] >> v[i];
	}

	solve();

	return 0;
}
